getCatalog.example:
// client
const bow = kcds.ui.EmoteWheel.getCatalog().find((emote) => emote.name === 'Bow');
if (bow) {
  kcds.core.Events.toServer('mannequinEmote', bow.fragment, bow.tags);
}

getCatalog.exampleCs:
// client
var bow = EmoteWheel.GetCatalog().FirstOrDefault(emote => emote["name"].AsString() == "Bow");
if (bow)
{
    Events.ToServer("mannequinEmote", bow["fragment"], bow["tags"]);
}
